class IntroSort<T extends Comparable<T>> implements Sorter<T> {
    private static final int INSERTION_SORT_THRESHOLD = 10;
    private final PivotSelector<T> pivotSelector;
    private final HeapSort<T> heapSort = new HeapSort<>();

