        System.out.println("╚════════════════════════════════════════════════════════╝\n");

        benchmarkSortingAlgorithms();
    }

    private static void benchmarkSortingAlgorithms() {
        int[] sizes = {1000, 10000, 100000};

        for (int size : sizes) {
            System.out.println("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
